/**
 * Core ServiceMediaMain Component
 * Provides low-level access to service main media via render props
 */
import React from 'react';
/**
 * Render props for MainMedia component
 */
export interface MainMediaRenderProps {
    /** Main media object containing the image string */
    mainMedia: {
        image?: string;
    };
    /** Whether the service has a main media image */
    hasMainMedia: boolean;
}
/**
 * Props for MainMedia component
 */
export interface MainMediaProps {
    /** Render prop function that receives main media data */
    children: (props: MainMediaRenderProps) => React.ReactNode;
}
/**
 * Core component that provides access to service main media via render props.
 * Must be used within a Service.Root context.
 *
 * @component
 * @example
 * ```tsx
 * <ServiceMediaMain.MainMedia>
 *   {({ mainMedia, hasMainMedia }) => (
 *     hasMainMedia ? (
 *       <img src={mainMedia.image} alt="Service" />
 *     ) : (
 *       <div>No image available</div>
 *     )
 *   )}
 * </ServiceMediaMain.MainMedia>
 * ```
 */
export declare function MainMedia(props: MainMediaProps): React.ReactNode;
